use super::*;
use store::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabaseLimits,SqliteSnapshotControl,SnapshotEncoding,SqliteSnapshotPhase,export_sqlite_database,import_sqlite_database}};

#[test]
fn sqlite_snapshot_space_controlled_native_output_retains_exact_fields_and_cancels_inside_unicode(){
 let(_,mut snapshot)=fixture();snapshot.schema="世界 🪐".repeat(30000);
 let limits=SqliteDatabaseLimits::default();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(SSpaceSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),snapshot);let mut interior=false;assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{if event.phase==SqliteSnapshotPhase::EncodeNative&&event.total==snapshot.schema.len()&&event.completed>=65536&&event.completed<event.total{interior=true;false}else{true}},limits)).is_err());assert!(interior);assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:snapshot.schema.len()-1,..limits})).is_err());assert!(snapshot.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:0,..limits})).is_err());}
}
fn fixture()->(serde_json::Value,SSpaceSnapshot){let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let s=&f["snapshot"];let artifacts=s["artifacts"].as_array().unwrap().iter().map(|r|SpaceArtifactRow{id:r["id"].as_str().unwrap().into(),name:r["name"].as_str().unwrap().into(),kind_id:r["kindId"].as_str().unwrap().into(),schema:r["schema"].as_str().unwrap().into(),dialect:SpaceArtifactDialect{artifact_kind:r["dialect"]["artifactKind"].as_str().unwrap().into(),standard:r["dialect"]["standard"].as_str().unwrap().into(),subset:r["dialect"]["subset"].as_str().unwrap().into()},created_at_ms:r["createdAtMs"].as_str().unwrap().parse().unwrap(),created_by:r["createdBy"].as_str().unwrap().into(),updated_at_ms:r["updatedAtMs"].as_str().unwrap().parse().unwrap(),updated_by:r["updatedBy"].as_str().unwrap().into()}).collect();let snapshot=SSpaceSnapshot{schema:s["schema"].as_str().unwrap().into(),space_id:s["spaceId"].as_str().unwrap().into(),artifacts};(f,snapshot)}
#[test]
fn sqlite_snapshot_space_full_occurrence_fields_and_independent_sqlite_edit(){
 use std::{process::{Command,Stdio},io::Write};let(f,snapshot)=fixture();let limits=SqliteDatabaseLimits::default();let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(SSpaceSnapshot::from_sqlite_database(&db,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),snapshot);
 let bytes=export_sqlite_database(&db,limits,&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=d.query('SELECT a.artifact_id,d.artifact_kind,a.created_at_ms_high AS high,a.created_at_ms_low AS low FROM space_artifact a JOIN space_artifact_dialect d ON d.id=a.id ORDER BY ordinal').all();if(r.length!==2||r[0].artifact_id!==r[1].artifact_id||r[0].artifact_kind!==''||r[0].high!==4294967295||r[0].low!==4294967295)throw Error('complete fields');const f=JSON.parse(process.argv[1]);d.exec('BEGIN');for(const sql of f.renumberSql)d.run(sql);d.exec('COMMIT');d.query('UPDATE space_artifact SET name=?,created_at_ms_high=?,created_at_ms_low=? WHERE ordinal=0').run(f.editedName,f.editedCreatedHigh,f.editedCreatedLow);await Bun.write(Bun.stdout,d.serialize());d.close();";
 let mut child=Command::new("bun").args(["-e",script]).arg(f.to_string()).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let actual=SSpaceSnapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,limits,&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();assert_eq!(actual.artifacts[0].name,f["editedName"].as_str().unwrap());assert_eq!(actual.artifacts[0].created_at_ms,(f["editedCreatedHigh"].as_u64().unwrap()<<32)|f["editedCreatedLow"].as_u64().unwrap());assert_eq!(actual.artifacts[1],snapshot.artifacts[1]);
}
#[test]
fn sqlite_snapshot_space_complete_guard_aliases_and_erased_native_controls(){
 let(f,snapshot)=fixture();let limits=SqliteDatabaseLimits::default();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.space.space".into(),standard:"1".into(),subset:"*".into()};let db=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();let codec=store::ArtifactCodec::bare::<SSpaceSnapshot,crate::SSpaceMutation>(crate::S_SPACE_INDEX_DOCUMENT_SCHEMA);let provider=codec.snapshot_sqlite.as_ref().unwrap();
 for wrong in f["invalidDialects"].as_array().unwrap(){let wrong=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:wrong["artifactKind"].as_str().unwrap().into(),standard:wrong["standard"].as_str().unwrap().into(),subset:wrong["subset"].as_str().unwrap().into()};assert!(snapshot.validate_sqlite_snapshot_subset(&wrong,&db,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}
 let mut aliases=db.clone();{let root=&mut aliases.table_mut("space_document").unwrap().rows[0];root.rowid=-17;root.values[0]=store::sqlite_snapshot::SqliteValue::Integer(-17);}for r in &mut aliases.table_mut("space_artifact").unwrap().rows{r.rowid=-r.rowid-100;r.values[0]=store::sqlite_snapshot::SqliteValue::Integer(r.rowid);r.values[1]=store::sqlite_snapshot::SqliteValue::Integer(-17);}for r in &mut aliases.table_mut("space_artifact_dialect").unwrap().rows{r.rowid=-r.rowid-100;r.values[0]=store::sqlite_snapshot::SqliteValue::Integer(r.rowid);}snapshot.validate_sqlite_snapshot_subset(&dialect,&aliases,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap();aliases.table_mut("space_artifact").unwrap().rows[0].values[4]=store::sqlite_snapshot::SqliteValue::Text("wrong name".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect,&aliases,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))};let db=(provider.export)(&codec.schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;let payload=(provider.import)(&codec.schema,&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap().value;assert_eq!(SSpaceSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),snapshot);assert!(SSpaceSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:4,..limits})).is_err());}
 let mut many=snapshot.clone();many.artifacts=vec![snapshot.artifacts[0].clone();f["deepRepeat"].as_u64().unwrap()as usize];for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(&many)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(&many))};assert_eq!(SSpaceSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),many);let mut stopped=false;assert!(SSpaceSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |e|{if e.phase==SqliteSnapshotPhase::DecodeNative&&e.completed>=256&&e.completed<e.total{stopped=true;false}else{true}},limits)).is_err());assert!(stopped);}
}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_space_actual_declared_typed_and_registry_erased_io(){
 use {semio_framework_artifact_reference::ArtifactDialect,store::io::io_mechanism::io_export_sqlite_snapshot,store::io::io_mechanism::io_import_sqlite_snapshot,store::io::io_mechanism::io_route,store::io::io_mechanism::io_run_with_snapshot_control};
 let plugin=semio_framework_plugin::Plugin::<semio_framework_plugin::plugin_app_close_prelude::NoPluginApp>::builder("space").label("Space index owning declaration").version("0.0.1").package_id("semio:space").artifact(crate::declaration().unwrap()).try_build().unwrap();let(_,snapshot)=fixture();let limits=SqliteDatabaseLimits::default();let dialect=ArtifactDialect{artifact_kind:"s.space.space".into(),standard:"1".into(),subset:"*".into()};let sqlite=ArtifactDialect::from(store::io_schema::SQLITE_SNAPSHOT);let export=io_route(&dialect,&sqlite,1).await.unwrap().value;let import=io_route(&sqlite,&dialect,1).await.unwrap().value;
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let file=io_export_sqlite_snapshot(&dialect,&snapshot,encoding,limits,&mut |_|true).await.unwrap().value;assert_eq!(io_import_sqlite_snapshot::<SSpaceSnapshot>(&dialect,&file,limits,&mut |_|true).await.unwrap().value,snapshot);let payload=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(&snapshot)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(&snapshot))};let file=io_run_with_snapshot_control(&export,payload,limits,&mut |_|true).await.unwrap().value;let payload=io_run_with_snapshot_control(&import,file,limits,&mut |_|true).await.unwrap().value;assert_eq!(SSpaceSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).unwrap(),snapshot);}drop(plugin);
}
